/**
 * bgTraffic.js — background traffic ("Hintergrundverkehr").
 *
 * The cars are SUMO trajectories generated by the backend
 * (backend/bg_traffic.py) and *played back*: by this module during the
 * preview, and by tools/bg_traffic_player.py inside a CARLA run, which puts
 * each car where the file says on every tick with physics off. Both sides
 * replay the same file, so for the background the preview is exact.
 *
 * With an „Umkreis" R (0 = the whole map) the traffic is a bubble that moves
 * with the ego: a car is shown only while it is within R of where the preview
 * has the ego at that moment — it appears where it drives into the bubble and
 * is removed where it leaves (R + 20 m), and „Fahrzeuge" is how many are
 * around the ego on average. The file holds one entry per shown stretch
 * ({t0, frames}); the player spawns and removes them at the same times.
 *
 * Replayed cars react to nothing, so the backend keeps every one of them clear
 * of the scenario — in space AND time: a car may cross a scripted actor's
 * path while that actor is at least KEEPOUT_TIME_S (8 s) away from the spot.
 * In CARLA the player adds an emergency stop for when timing differs. Paths: this module sends it the KEEP-OUT — every path the preview
 * predicts for the ego and the NPCs (Simulate.runHeadless), each route's full
 * lane-following line and trajectory, every spawn pose and every prop, each
 * with the half-width of what drives it — and the backend drops any car that
 * comes within `clearance` of one, re-simulating the rest. A scenario edit
 * changes the keep-out, so the traffic is regenerated (debounced) after one;
 * the request is its own cache key on both sides.
 *
 * Settings live on AppState.bgTraffic ({enabled, count, seed, clearance, radius}),
 * saved with the scenario like weather/time and kept out of undo.
 */
(function () {
  'use strict';

  const DEBOUNCE_MS = 900;
  const KEEPOUT_STEP_M = 1.0; // keep-out polyline sample spacing
  const FOCUS_STEP_M = 5.0; // focus polylines: the zone is tens of metres wide
  const KEEPOUT_SIM_S = 60; // every Act's MaxSimTime

  const panel = document.getElementById('env-menu-panel');
  const cbEnabled = document.getElementById('bg-enabled');
  const inCount = document.getElementById('bg-count');
  const inSeed = document.getElementById('bg-seed');
  const btnReseed = document.getElementById('bg-reseed');
  const inClear = document.getElementById('bg-clearance');
  const inRadius = document.getElementById('bg-radius');
  const statusEl = document.getElementById('bg-status');
  const layer = document.getElementById('layer-bg-traffic');
  const SVG_NS = 'http://www.w3.org/2000/svg';

  let _data = null; // last result from the backend
  let _dataSig = null; // the request signature _data answers
  let _lastReq = null; // the last request sent (its body)
  let _pending = null; // {sig, promise} of an in-flight request
  let _error = null;
  let _timer = null;
  let _deferred = false; // a regeneration is due once the preview stops
  let _lastT = null; // preview time last drawn, null when not previewing
  let _drawnKey = null; // which _data the layer's elements belong to
  let _els = [];

  const settings = () => AppState.bgTraffic;
  const active = () => !!(settings().enabled && AppState.map);

  // ── Keep-out ────────────────────────────────────────────────────────────

  function _halfWidth(type) {
    const sz = MapView.actorSize(type) || { w: 4.5, h: 2.1 };
    return (sz.h || sz.w) / 2;
  }

  /** Thin a timed track [{x, y, t}] to a point per metre moved or per second
   *  passed — a standing actor keeps its points, so the backend sees how long
   *  it occupies its spot. Returns [[x, y, t], …]. */
  function _thinTimed(points) {
    const out = [];
    const r1 = (v) => Math.round(v * 10) / 10;
    for (const p of points) {
      const last = out[out.length - 1];
      if (!last || Math.hypot(p.x - last[0], p.y - last[1]) >= KEEPOUT_STEP_M || p.t - last[2] >= 1) {
        out.push([r1(p.x), r1(p.y), r1(p.t)]);
      }
    }
    const end = points[points.length - 1];
    if (end && out.length && out[out.length - 1][2] !== r1(end.t)) out.push([r1(end.x), r1(end.y), r1(end.t)]);
    return out;
  }

  /** The part of an authored path the preview's track does not reach: from
   *  the path point nearest the track's last point on. */
  function _remainder(pts, last) {
    if (!pts.length || !last) return pts;
    let best = 0,
      bestD = Infinity;
    pts.forEach((p, i) => {
      const d = Math.hypot(p.x - last.x, p.y - last.y);
      if (d < bestD) {
        bestD = d;
        best = i;
      }
    });
    return pts.slice(best);
  }

  /** Thin a polyline to ~`step` spacing, always keeping both ends. */
  function _thin(points, step = KEEPOUT_STEP_M) {
    const out = [];
    for (const p of points) {
      if (!p || !Number.isFinite(p.x) || !Number.isFinite(p.y)) continue;
      const last = out[out.length - 1];
      if (!last || Math.hypot(p.x - last[0], p.y - last[1]) >= step) {
        out.push([Math.round(p.x * 10) / 10, Math.round(p.y * 10) / 10]);
      }
    }
    const end = points[points.length - 1];
    if (
      end &&
      out.length &&
      (out[out.length - 1][0] !== Math.round(end.x * 10) / 10 || out[out.length - 1][1] !== Math.round(end.y * 10) / 10)
    ) {
      out.push([Math.round(end.x * 10) / 10, Math.round(end.y * 10) / 10]);
    }
    return out;
  }

  /**
   * The keep-out (`keepout`, as {w, pts}): each scripted actor's predicted
   * track WITH times ([x, y, t] — a background car may cross it while the
   * actor is far enough away in time, backend KEEPOUT_TIME_S), the part of its
   * authored path the preview never reaches (timed at the track's end), and
   * WITHOUT times ([x, y] — occupied for the whole run) every prop. Plus the
   * ego's paths as plain polylines (`focus`, where its bubble goes) and its
   * timed track (`track`). Null while a preview runs: runHeadless shares its
   * tick state and refuses, and the preview's poses are not the authored ones.
   */
  /** Whether the scripted ego brakes for obstacles in CARLA (its default). */
  const egoReacts = () => !!AppState.ego && AppState.ego.obey_obstacles !== false;

  function _scenarioPaths() {
    if (Simulate.running) return null;
    const actors = [AppState.ego, ...AppState.npcs].filter(Boolean);
    const paths = [];
    const focus = [];
    let egoTrack = null; // the ego's [[t, x, y], …], every 0.5 s
    const run = actors.length
      ? // The ego brakes for what is in its path when it obeys obstacles, as the
        // scripted ego does in CARLA; the non-reacting preview ego drives through
        // a braking lead and runs up to ~60 m ahead of the real one.
        Simulate.runHeadless({
          dt: 0.1,
          maxTime: KEEPOUT_SIM_S,
          props: AppState.staticObjects || [],
          reactiveEgo: egoReacts(),
        })
      : null;
    for (const a of actors) {
      const w = _halfWidth(AppState.bodyType(a));
      const isEgo = a === AppState.ego;
      const track = run && run.tracks[a.id];
      const timed = [{ x: a.x, y: a.y, t: 0 }, ...(track || []).map((p, i) => ({ x: p.x, y: p.y, t: run.times[i] }))];
      const lastPos = timed[timed.length - 1];
      // A stopped actor's spot stays covered: the track keeps a point per
      // second there, each blocking ±KEEPOUT_TIME_S, past the window's end.
      paths.push({ w, pts: _thinTimed(timed) });
      if (track && track.length) {
        if (isEgo) {
          focus.push(_thin([{ x: a.x, y: a.y }, ...track], FOCUS_STEP_M));
          const r1 = (v) => Math.round(v * 10) / 10;
          egoTrack = [[0, r1(a.x), r1(a.y)]];
          track.forEach((p, i) => {
            if (i % 5 === 4) egoTrack.push([Math.round(run.times[i] * 100) / 100, r1(p.x), r1(p.y)]);
          });
        }
      }
      // The authored paths too, in full: CARLA may drive further than the
      // preview's 60 s, and a trajectory past a freeze is still where it goes.
      for (const ev of a.events || []) {
        const act = ev.action || {};
        let pts = null;
        if (act.type === 'follow_trajectory') pts = act.trajectory || [];
        else if (act.type === 'assign_route') {
          pts = Simulate.routeGeometry(a, ev) || act.waypoints || [];
        }
        if (pts && pts.length) {
          // Past the preview's end, timed at that end: CARLA may get further.
          const rest = _remainder(pts, lastPos);
          if (rest.length > 1)
            paths.push({ w, pts: _thin(rest).map((p) => [p[0], p[1], Math.round(lastPos.t * 10) / 10]) });
          if (isEgo) focus.push(_thin([{ x: a.x, y: a.y }, ...pts], FOCUS_STEP_M));
        }
      }
    }
    for (const o of AppState.staticObjects || []) {
      const ps = window.PropCatalog?.planSize ? PropCatalog.planSize(o.prop) : null;
      const w = ps ? Math.max(ps.len, ps.wid) / 2 : 1;
      paths.push({ w: Math.round(w * 100) / 100, pts: [[Math.round(o.x * 10) / 10, Math.round(o.y * 10) / 10]] });
    }
    // An ego that has not been placed or does not move still focuses on
    // where it stands.
    if (AppState.ego && !focus.length) {
      focus.push([[Math.round(AppState.ego.x * 10) / 10, Math.round(AppState.ego.y * 10) / 10]]);
    }
    if (AppState.ego && !egoTrack) egoTrack = [[0, focus[0][0][0], focus[0][0][1]]];
    return { keepout: paths, focus, track: egoTrack };
  }

  function _requestBody() {
    const s = settings();
    const sp = _scenarioPaths();
    if (sp === null) return null;
    const radius = Math.max(0, Math.min(500, +s.radius || 0));
    return {
      town: AppState.map,
      seed: Math.max(0, Math.round(+s.seed || 0)),
      count: Math.max(1, Math.min(200, Math.round(+s.count || 1))),
      clearance: Math.max(0, Math.min(20, +s.clearance || 0)),
      keepout: sp.keepout,
      // Radius 0, or no ego: the whole map. Otherwise a bubble around the ego:
      // `paths` is where it drives (where trips start and end), `track` when
      // it is where (what is shown when).
      focus: radius > 0 && sp.focus.length && sp.track ? { radius, paths: sp.focus, track: sp.track } : null,
    };
  }

  // ── Generation ──────────────────────────────────────────────────────────

  async function _fetch(body) {
    const res = await fetch('/api/bg_traffic', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    if (!res.ok) {
      let msg = `${res.status}`;
      try {
        msg = (await res.json()).detail || msg;
      } catch (_) {
        /* not JSON */
      }
      throw new Error(msg);
    }
    return res.json();
  }

  /**
   * The traffic for the scenario as it is now, generated if needed.
   * Resolves to null when traffic is off. While a preview runs the last
   * request stands (the scenario cannot be edited then anyway).
   */
  function ensure() {
    if (!active()) return Promise.resolve(null);
    const body = _requestBody() || _lastReq;
    if (!body) return Promise.resolve(null);
    const sig = JSON.stringify(body);
    if (_data && _dataSig === sig) return Promise.resolve(_data);
    if (_pending && _pending.sig === sig) return _pending.promise;
    _lastReq = body;
    _error = null;
    const promise = _fetch(body).then(
      (data) => {
        if (_pending && _pending.sig === sig) _pending = null;
        _data = data;
        _dataSig = sig;
        _renderStatus();
        if (_lastT !== null) _draw(_lastT);
        return data;
      },
      (err) => {
        if (_pending && _pending.sig === sig) _pending = null;
        _error = err.message;
        _renderStatus();
        throw err;
      },
    );
    _pending = { sig, promise };
    _renderStatus();
    return promise;
  }

  function _schedule() {
    if (!active()) return;
    clearTimeout(_timer);
    if (Simulate.running) {
      _deferred = true;
      _renderStatus();
      return;
    }
    _timer = setTimeout(() => {
      _timer = null;
      if (Simulate.running) {
        _deferred = true;
        _renderStatus();
        return;
      }
      ensure().catch(() => {
        /* shown in the status line */
      });
    }, DEBOUNCE_MS);
    _renderStatus();
  }

  // ── Status / settings UI ────────────────────────────────────────────────

  function _renderStatus() {
    panel.classList.toggle('bg-off', !settings().enabled);
    let text = 'Aus',
      cls = '';
    if (!settings().enabled) {
      text = 'Aus';
    } else if (!AppState.map) {
      text = 'Keine Karte geladen';
    } else if (_error && !_pending) {
      text = `Fehler: ${_error}`;
      cls = 'error';
    } else if (_pending || _timer) {
      text = 'Wird erzeugt …';
      cls = 'busy';
    } else if (_deferred) {
      text = 'Veraltet — wird nach der Vorschau neu erzeugt';
    } else if (_data && _data.town === AppState.map) {
      if (_data.focus_radius) {
        // Bubble: the count is the average number around the ego at a time.
        const avg = (_data.stats && _data.stats.visible_avg) || 0;
        const cars = new Set(_data.vehicles.map((v) => v.car || v.id)).size;
        const fmt = String(Math.round(avg)).replace('.', ',');
        text =
          avg < 0.85 * _data.requested
            ? `Ø ${fmt} von ${_data.requested} Fahrzeugen im Umkreis von ${_data.focus_radius} m — mehr passen nicht neben das Szenario`
            : `Ø ${fmt} Fahrzeuge im Umkreis von ${_data.focus_radius} m (${cars} insgesamt)`;
      } else {
        const n = _data.vehicles.length;
        text =
          n < _data.requested
            ? `${n} von ${_data.requested} Fahrzeugen — mehr passen nicht neben das Szenario`
            : `${n} Fahrzeuge`;
      }
      if (_data.stats && _data.stats.seconds != null) text += ` · ${String(_data.stats.seconds).replace('.', ',')} s`;
    }
    statusEl.textContent = text;
    statusEl.className = `bg-status ${cls}`;
  }

  function _syncInputs() {
    const s = settings();
    cbEnabled.checked = !!s.enabled;
    inCount.value = s.count;
    inSeed.value = s.seed;
    inClear.value = s.clearance;
    inRadius.value = s.radius;
    _renderStatus();
  }

  function _update(patch) {
    AppState.bgTraffic = { ...settings(), ...patch };
    if (!AppState.bgTraffic.enabled) {
      clearTimeout(_timer);
      _timer = null;
      _deferred = false;
      _clear();
    }
    _renderStatus();
    _schedule();
  }

  cbEnabled.addEventListener('change', () => _update({ enabled: cbEnabled.checked }));
  inCount.addEventListener('change', () => {
    const n = Math.max(1, Math.min(200, Math.round(+inCount.value || 1)));
    inCount.value = n;
    _update({ count: n });
  });
  inSeed.addEventListener('change', () => {
    const n = Math.max(0, Math.round(+inSeed.value || 0));
    inSeed.value = n;
    _update({ seed: n });
  });
  inClear.addEventListener('change', () => {
    const v = Math.max(0, Math.min(20, +inClear.value || 0));
    inClear.value = v;
    _update({ clearance: v });
  });
  inRadius.addEventListener('change', () => {
    const v = Math.max(0, Math.min(500, Math.round(+inRadius.value || 0)));
    inRadius.value = v;
    _update({ radius: v });
  });
  btnReseed.addEventListener('click', () => {
    const n = Math.floor(Math.random() * 100000);
    inSeed.value = n;
    _update({ seed: n });
  });

  // ── Drawing (preview only) ──────────────────────────────────────────────

  function _clear() {
    while (layer.firstChild) layer.removeChild(layer.firstChild);
    _els = [];
    _drawnKey = null;
  }

  function _build(data) {
    _clear();
    for (const v of data.vehicles) {
      const g = document.createElementNS(SVG_NS, 'g');
      g.setAttribute('class', 'bg-car-group');
      const L = v.length,
        W = v.width;
      const body = document.createElementNS(SVG_NS, 'rect');
      body.setAttribute('class', 'bg-car');
      body.setAttribute('x', String(-L / 2));
      body.setAttribute('y', String(-W / 2));
      body.setAttribute('width', String(L));
      body.setAttribute('height', String(W));
      body.setAttribute('rx', '0.4');
      const nose = document.createElementNS(SVG_NS, 'rect');
      nose.setAttribute('class', 'bg-car-nose');
      nose.setAttribute('x', String(L / 2 - 1.3));
      nose.setAttribute('y', String(-W / 2 + 0.2));
      nose.setAttribute('width', '0.5');
      nose.setAttribute('height', String(W - 0.4));
      g.appendChild(body);
      g.appendChild(nose);
      layer.appendChild(g);
      _els.push(g);
    }
    _drawnKey = data.key;
  }

  /**
   * Pose [x, y, yaw] of one entry at time t, interpolated like the player does,
   * or null outside the entry's life [t0, t0 + (frames − 1)·dt] — with a
   * focus a car exists only while it is near the ego.
   */
  function poseAt(v, t, dt) {
    const fr = v.frames;
    const f = (t - (v.t0 || 0)) / dt;
    if (f < -1e-6 || f > fr.length - 1 + 1e-6) return null;
    const i = Math.floor(f);
    if (i <= 0) return [fr[0][0], fr[0][1], fr[0][3]];
    if (i >= fr.length - 1) {
      const l = fr[fr.length - 1];
      return [l[0], l[1], l[3]];
    }
    const a = fr[i],
      b = fr[i + 1],
      w = f - i;
    const dyaw = ((b[3] - a[3] + 540) % 360) - 180;
    return [a[0] + (b[0] - a[0]) * w, a[1] + (b[1] - a[1]) * w, a[3] + dyaw * w];
  }

  function _draw(t) {
    if (!active() || !_data || _data.town !== AppState.map || !_data.vehicles.length) {
      if (_els.length) _clear();
      return;
    }
    if (_drawnKey !== _data.key) _build(_data);
    const dt = _data.dt;
    _data.vehicles.forEach((v, i) => {
      const pose = poseAt(v, t, dt);
      if (!pose) {
        _els[i].style.display = 'none';
        return;
      }
      const [x, y, yaw] = pose;
      _els[i].style.display = '';
      _els[i].setAttribute('transform', `translate(${x.toFixed(2)},${y.toFixed(2)}) rotate(${yaw.toFixed(1)})`);
    });
  }

  Simulate.onTime((t) => {
    _lastT = t;
    if (t === null) {
      _clear();
      if (_deferred) {
        _deferred = false;
        _schedule();
      }
      return;
    }
    _draw(t);
  });

  // ── Re-generation triggers ──────────────────────────────────────────────

  // Editor-only keys never change the keep-out; weather/time are not traffic.
  const IGNORED_KEYS = new Set([
    'selectedId',
    'selectedTrafficLightId',
    'selectedWaypoint',
    'activeTool',
    'pendingTemplate',
    'pendingProp',
    'pendingGenerate',
    'trajectoryMode',
    'activeTrajectoryId',
    'routeMode',
    'activeRouteId',
    'activePathEventId',
    'weather',
    'time',
    'userTemplates',
    'specialBuildings',
  ]);
  AppState.on('change', (patch) => {
    const keys = Object.keys(patch || {});
    if (keys.includes('map') || keys.includes('mapData') || keys.includes('laneGraph')) {
      _clear();
      _renderStatus();
    }
    if (keys.length && keys.every((k) => IGNORED_KEYS.has(k))) return;
    if (!Simulate.running) _schedule();
  });
  for (const evt of ['actorUpdated', 'actorRemoved']) {
    AppState.on(evt, () => {
      if (!Simulate.running) _schedule();
    });
  }
  AppState.on('stateLoaded', () => {
    _syncInputs();
    _schedule();
  });

  // ── Export ──────────────────────────────────────────────────────────────

  /**
   * The .xosc and its traffic, zipped (POST /api/export/bundle). `params` is
   * the ordinary export payload. Resolves to {blob, vehicles}.
   */
  async function exportBundle(params) {
    const data = await ensure();
    if (!data) throw new Error('Hintergrundverkehr ist aus');
    const res = await fetch('/api/export/bundle', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ params, bg_traffic: _lastReq }),
    });
    if (!res.ok) {
      const msg = await res.text();
      throw new Error(`Export failed (${res.status}): ${msg}`);
    }
    return {
      blob: await res.blob(),
      vehicles: Number(res.headers.get('X-Bg-Traffic-Vehicles') || data.vehicles.length),
    };
  }

  _syncInputs();

  window.BgTraffic = {
    get active() {
      return active();
    },
    get data() {
      return _data;
    },
    get busy() {
      return !!(_pending || _timer);
    },
    ensure,
    exportBundle,
    poseAt,
  };
})();
